import os
from openai import OpenAI


def embed_for_search(payload, config=None):
    config = config or {}
    with OpenAI(api_key=config.get('api_key') or os.environ['OPENAI_API_KEY']) as client:
        query_response = client.embeddings.create(model='text-embedding-3-small', input=payload['query'])
        documents_response = client.embeddings.create(model='text-embedding-3-small', input=payload['documents'])

    return {
        'query_embedding': query_response.data[0].embedding,
        'document_embeddings': [item.embedding for item in documents_response.data]
    }

import os
from openai import OpenAI


class EmbeddingsClient:
    def __init__(self, api_key=None, model='text-embedding-3-small'):
        self.api_key = api_key or os.environ.get('OPENAI_API_KEY')
        if not self.api_key:
            raise ValueError("OpenAI API key not provided and not found in environment variables.")
        self.client = OpenAI(api_key=self.api_key)
        self.model = model

    def get_embedding(self, text):
        response = self.client.embeddings.create(model=self.model, input=text)
        return response.data[0].embedding

    def get_batch_embeddings(self, texts):
        response = self.client.embeddings.create(model=self.model, input=texts)
        return [item.embedding for item in response.data]

from typing import List, Dict, Any


class EmbeddingRequest:
    def __init__(self, texts: List[str], model: str = 'text-embedding-3-small'):
        self.texts = texts
        self.model = model

    def to_openai_payload(self) -> Dict[str, Any]:
        return {
            'input': self.texts,
            'model': self.model,
        }


class EmbeddingResponse:
    def __init__(self, openai_response: Any):
        self.embeddings = [item.embedding for item in openai_response.data]
        self.model = openai_response.model

    def to_dict(self) -> Dict[str, Any]:
        return {
            'embeddings': self.embeddings,
            'model': self.model,
        }

def embedding_job_summary(payload):
    embeddings = payload['embeddings']
    summary = {
        'total_embeddings': len(embeddings),
        'embedding_dimension': len(embeddings[0]) if embeddings else 0,
        'first_embedding_sample': embeddings[0][:5] if embeddings else []  # Show first 5 dimensions as sample
    }
    return summary

import os
from openai import OpenAI


def corpus_safety(payload, config=None):
    config = config or {}
    with OpenAI(api_key=config.get('api_key') or os.environ['OPENAI_API_KEY']) as client:
        moderation_response = client.moderations.create(input=payload['text'])

    results = moderation_response.results[0]

    if results.flagged:
        return {
            'is_safe': False,
            'categories': {category: value for category, value in results.categories.model_dump().items() if value},
            'category_scores': {category: value for category, value in results.category_scores.model_dump().items()}
        }
    else:
        return {'is_safe': True}

import os
from google.cloud import translate_v2 as translate


def multilingual_query_translate(payload, config=None):
    config = config or {}
    # Ensure GOOGLE_APPLICATION_CREDENTIALS is set for authentication
    # For local development, you might set it via environment variable or gcloud auth application-default login
    translate_client = translate.Client()

    target_language = payload.get('target_language', 'en')
    queries = payload['queries']

    translated_queries = []
    for query in queries:
        result = translate_client.translate(query, target_language=target_language)
        translated_queries.append({
            'original_text': query,
            'translated_text': result['translatedText'],
            'detected_source_language': result['detectedSourceLanguage']
        })

    return {'translated_queries': translated_queries}
